from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, array, i, j):
        pass

    @abstractmethod
    def sort(self, array):
        pass

class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a - b if isinstance(a, int) else a.lower() > b.lower()

    def swap(self, array, i, j):
        array[i], array[j] = array[j], array[i]

    def sort(self, array):
        n = len(array)
        for i in range(n):
            for j in range(0, n-i-1):
                if self.compare(array[j], array[j+1]) > 0:
                    self.swap(array, j, j+1)

class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        return a - b if isinstance(a, int) else a.lower() > b.lower()

    def swap(self, array, i, j):
        array[i], array[j] = array[j], array[i]

    def sort(self, array):
        n = len(array)
        for i in range(n):
            min_idx = i
            for j in range(i+1, n):
                if self.compare(array[j], array[min_idx]) < 0:
                    min_idx = j
            self.swap(array, i, min_idx)

# Testing
